       --shadow: 0 24px 60px rgba(15, 23, 42, 0.14);
       --radius: 22px;
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
       background:
         radial-gradient(circle at top left, rgba(37, 99, 235, 0.14), transparent 30%),
         radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.12), transparent 34%),
         var(--bg);
       color: var(--text);
       display: grid;
       place-items: center;
       padding: 32px 16px;
     }

     .page-shell {
       width: min(100%, 1040px);
       display: grid;
       grid-template-columns: minmax(260px, 420px) minmax(320px, 1fr);
       gap: 24px;
       align-items: stretch;
     }

     .hero,
     .form-card {
       background: var(--panel);
       backdrop-filter: blur(10px);
       border: 1px solid var(--panel-border);
       border-radius: var(--radius);
       box-shadow: var(--shadow);
     }

     .hero {
       padding: 40px;
       display: flex;
       flex-direction: column;
       justify-content: space-between;
       gap: 24px;
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       gap: 8px;
       padding: 8px 14px;
       width: fit-content;
       border-radius: 999px;
       background: rgba(37, 99, 235, 0.1);
       color: var(--accent);
       font-weight: 700;
       font-size: 0.84rem;
       letter-spacing: 0.02em;
     }

     h1 {
       margin: 0;
       font-size: clamp(2rem, 4vw, 3.2rem);
       line-height: 1.05;
       letter-spacing: -0.04em;
     }

     .hero p {
       margin: 0;
       color: var(--muted);
       font-size: 1.02rem;
       line-height: 1.7;
       max-width: 32ch;
     }

     .hero-stats {
       display: flex;
       gap: 16px;
       flex-wrap: wrap;
     }

     .stat {
       flex: 1 1 120px;
       padding: 18px;
       border-radius: 18px;
       background: rgba(15, 23, 42, 0.04);
     }

     .stat strong {
       display: block;
       font-size: 1.2rem;
       margin-bottom: 4px;
     }

     .stat span {
       color: var(--muted);
       font-size: 0.92rem;
     }

     .form-card {
       padding: 32px;
     }

     .form-header h2 {
       margin: 0 0 8px;
       font-size: 1.6rem;
       letter-spacing: -0.03em;
     }

     .form-header p {
       margin: 0 0 24px;
       color: var(--muted);
       line-height: 1.6;
     }

     form {
       display: grid;
       gap: 18px;
     }

     .form-field {
       display: grid;
       gap: 8px;
     }

     label {
       font-weight: 700;
       font-size: 0.96rem;
     }

     input {
       width: 100%;
       border: 1px solid #cbd5e1;
       border-radius: 14px;
       padding: 14px 16px;
       font: inherit;
       color: var(--text);
       background: #fff;
       transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
     }

     input::placeholder {
       color: #94a3b8;
     }

     input:focus {
       outline: none;
       border-color: var(--accent);
       box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.14);
       transform: translateY(-1px);
     }

     .helper-text,
     .error-message,
     .success-message {
       font-size: 0.92rem;
       line-height: 1.4;
       margin: 0;
     }

     .helper-text {
       color: var(--muted);
     }

     .error-message {
       color: var(--danger);
       min-height: 1.3em;
     }

     .form-field.has-error input {
       border-color: rgba(220, 38, 38, 0.7);
       box-shadow: 0 0 0 4px rgba(220, 38, 38, 0.1);
     }

     .submit-button {
       border: 0;
       border-radius: 14px;
       padding: 15px 20px;
       font: inherit;
       font-weight: 700;
       color: #fff;
       background: linear-gradient(135deg, var(--accent), var(--accent-dark));
       cursor: pointer;
       transition: transform 0.2s ease, box-shadow 0.2s ease, opacity 0.2s ease;
       box-shadow: 0 18px 30px rgba(37, 99, 235, 0.24);
     }

     .submit-button:hover,
     .submit-button:focus-visible {
       transform: translateY(-1px);
       box-shadow: 0 22px 34px rgba(37, 99, 235, 0.3);
     }

     .submit-button:focus-visible {
       outline: 3px solid rgba(37, 99, 235, 0.24);
       outline-offset: 2px;
     }

     .success-message {
       color: var(--success);
       min-height: 1.3em;
     }

     @media (max-width: 860px) {
       .page-shell {
         grid-template-columns: 1fr;
       }

       .hero,
       .form-card {
         padding: 28px;
       }
     }
