         <h2>Contact support</h2>
         <p>Fields marked as required must be completed before submitting.</p>
       </div>

       <form id="support-form" novalidate>
         <div class="form-field" data-field="fullName">
           <label for="fullName">Full name *</label>
           <input
             id="fullName"
             name="fullName"
             type="text"
             autocomplete="name"
             placeholder="Jane Smith"
             required
             aria-describedby="fullName-error"
           >
           <p id="fullName-error" class="error-message" aria-live="polite"></p>
         </div>

         <div class="form-field" data-field="email">
           <label for="email">Email address *</label>
           <input
             id="email"
             name="email"
             type="email"
             autocomplete="email"
             placeholder="jane@company.com"
             required
             aria-describedby="email-error"
           >
           <p id="email-error" class="error-message" aria-live="polite"></p>
         </div>

         <div class="form-field" data-field="phone">
           <label for="phone">Phone number</label>
           <input
             id="phone"
             name="phone"
             type="tel"
             autocomplete="tel"
             placeholder="+1 (555) 123-4567"
             aria-describedby="phone-help phone-error"
           >
           <p id="phone-help" class="helper-text">Optional. Use digits and include country code if needed, for example +1 (555) 123-4567.</p>
           <p id="phone-error" class="error-message" aria-live="polite"></p>
         </div>

         <button class="submit-button" type="submit">Submit request</button>
         <p id="form-success" class="success-message" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById("support-form");
     const successMessage = document.getElementById("form-success");

     const fields = {
       fullName: {
         input: document.getElementById("fullName"),
         error: document.getElementById("fullName-error"),
         validate(value) {
           if (!value.trim()) {
             return "Full name is required.";
           }
           return "";
         }
       },
       email: {
         input: document.getElementById("email"),
         error: document.getElementById("email-error"),
         validate(value) {
           if (!value.trim()) {
             return "Email address is required.";
           }

           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
           if (!emailPattern.test(value.trim())) {
             return "Enter a valid email address.";
           }

           return "";
         }
       },
       phone: {
         input: document.getElementById("phone"),
         error: document.getElementById("phone-error"),
         validate(value) {
           const trimmedValue = value.trim();
           if (!trimmedValue) {
             return "";
           }

           const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;
           if (!phonePattern.test(trimmedValue)) {
             return "Enter a valid phone number using digits, spaces, dashes, or parentheses.";
           }

           return "";
         }
       }
     };

     function updateFieldState(fieldName) {
       const field = fields[fieldName];
       const message = field.validate(field.input.value);
       const wrapper = field.input.closest(".form-field");

       field.error.textContent = message;
       wrapper.classList.toggle("has-error", Boolean(message));
       field.input.setAttribute("aria-invalid", message ? "true" : "false");

       return !message;
     }

     Object.keys(fields).forEach((fieldName) => {
       const { input } = fields[fieldName];
       input.addEventListener("blur", () => updateFieldState(fieldName));
       input.addEventListener("input", () => {
         if (input.getAttribute("aria-invalid") === "true") {
           updateFieldState(fieldName);
         }
         successMessage.textContent = "";
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const formIsValid = Object.keys(fields)
         .map((fieldName) => updateFieldState(fieldName))
         .every(Boolean);

       if (!formIsValid) {
         successMessage.textContent = "";
         return;
       }

       successMessage.textContent = "Your support request has been submitted.";
       form.reset();

       Object.keys(fields).forEach((fieldName) => {
         fields[fieldName].input.setAttribute("aria-invalid", "false");
         fields[fieldName].input.closest(".form-field").classList.remove("has-error");
       });
     });
   </script>
 </body>
 </html>

